func (v TaggerValue) Type(ctx context.Context) attr.Type {
	return TaggerType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v TaggerValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"date":  basetypes.StringType{},
		"email": basetypes.StringType{},
		"name":  basetypes.StringType{},
	}
}
